// Create a new AvahiStringList from 0-3 randomly generated C-strings, terminated with a NULL sentinel.
// Each argument must be a NUL-terminated string; we use FUZZ_PARAM_STR() and pass .c_str().
// The varargs must end with NULL.
AvahiStringList *l = nullptr;
unsigned int n = (*FUZZ_PARAM(unsigned int)) % 4; // 0..3 strings
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
std::string s3 = FUZZ_PARAM_STR();
// Dispatch on count to ensure correct varargs usage and a final NULL sentinel.
switch (n) {
    case 0:
        l = avahi_string_list_new(NULL);
        break;
    case 1:
        l = avahi_string_list_new(s1.c_str(), NULL);
        break;
    case 2:
        l = avahi_string_list_new(s1.c_str(), s2.c_str(), NULL);
        break;
    default:
        l = avahi_string_list_new(s1.c_str(), s2.c_str(), s3.c_str(), NULL);
        break;
}
// If allocation fails, bail to avoid handing a NULL object to the pool.
if (!l) { FUZZ_BAIL(); }
// Validation: Ensures varargs end with NULL and strings are properly NUL-terminated; returns a non-NULL list head.

// Build a small array (0-3 entries) of valid C-strings or a NULL-terminated array when length == -1.
AvahiStringList *l = nullptr;
unsigned int count = (*FUZZ_PARAM(unsigned int)) % 4; // 0..3
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
std::string s3 = FUZZ_PARAM_STR();
int mode = (int)((*FUZZ_PARAM(unsigned int)) % 2); // 0 => explicit length, 1 => -1 with NULL-terminated array
// Prepare storage with room for NULL terminator
const char *arr4[4] = { nullptr, nullptr, nullptr, nullptr };
if (count > 0) arr4[0] = s1.c_str();
if (count > 1) arr4[1] = s2.c_str();
if (count > 2) arr4[2] = s3.c_str();
if (mode == 0) {
    l = avahi_string_list_new_from_array((const char **)arr4, (int)count);
} else {
    // length == -1 requires the array to be NULL-terminated; arr4 already ends with NULL
    l = avahi_string_list_new_from_array((const char **)arr4, -1);
}
if (!l && count != 0) { FUZZ_BAIL(); }
// Validation: Constrains array shape for both explicit length and NULL-terminated modes; returns list head (may be NULL when count==0 acceptable).

// Free the list. Accepts NULL or a valid list allocated by this API.
avahi_string_list_free(l);
// Validation: Post-call, l must not be used; we do not return it to the pool.

// Append (prepend internally) a NUL-terminated string; use returned head afterward.
std::string text = FUZZ_PARAM_STR();
AvahiStringList *l_new = avahi_string_list_add(l, text.c_str());
if (!l_new) { FUZZ_BAIL(); }
// Do not return old 'l' to avoid duplicate handles to the same list.
// Validation: Ensures valid input string and head replacement semantics.

// Use a safe, simple printf-style format with matching varargs to avoid UB.
// Format: "%s-%u"
std::string s = FUZZ_PARAM_STR();
unsigned int u = *FUZZ_PARAM(unsigned int);
AvahiStringList *l_new = avahi_string_list_add_printf(l, "%s-%u", s.c_str(), u);
if (!l_new) { FUZZ_BAIL(); }
// Validation: Provides a valid format and matching arguments; uses returned list head only.

// Append arbitrary bytes; source may contain NULs. We take data() and size() from a fuzzed string.
