AvahiStringList *out = nullptr;
int rc = avahi_string_list_parse((const void*)data.data(), data.size(), &out);
if (rc < 0 || !out) { FUZZ_BAIL(); }
// Validation: Ensures ret pointer is non-NULL on success and hands ownership of the created list to the pool.

