if (!client) { delete poll_api; ::operator delete(cbdata); FUZZ_BAIL(); }
FUZZ_SET_ATTR_PTR(client, "poll_api", (void*)poll_api);
FUZZ_SET_ATTR_PTR(client, "cbdata", (void*)cbdata);

// Prepare parameters for avahi_record_browser_new().
AvahiIfIndex iface = (AvahiIfIndex)((int)(*FUZZ_PARAM(int)));
AvahiProtocol proto = (AvahiProtocol)((int)(*FUZZ_PARAM(int)));
std::string name_s = FUZZ_PARAM_STR();
if (name_s.empty()) name_s = "_services._dns-sd._udp.local"; // common safe owner name
if (name_s.size() > 240) name_s.resize(240);
const char *name = name_s.c_str();
uint16_t clazz = (uint16_t)(*FUZZ_PARAM(unsigned int));
uint16_t rtype = (uint16_t)(*FUZZ_PARAM(unsigned int));
AvahiLookupFlags lflags = (AvahiLookupFlags)((*FUZZ_PARAM(unsigned int)) & (AVAHI_LOOKUP_USE_WIDE_AREA|AVAHI_LOOKUP_USE_MULTICAST|AVAHI_LOOKUP_NO_TXT|AVAHI_LOOKUP_NO_ADDRESS));

AvahiRecordBrowserCallback rb_cb = +[](AvahiRecordBrowser *b, AvahiIfIndex i, AvahiProtocol p, AvahiBrowserEvent e, const char *n, uint16_t c, uint16_t t, const void *rdata, size_t size, AvahiLookupResultFlags f, void *ud){
    (void)b; (void)i; (void)p; (void)e; (void)n; (void)c; (void)t; (void)rdata; (void)size; (void)f; (void)ud; };
void *userdata = (void*)client;

AvahiRecordBrowser *browser = avahi_record_browser_new(client, iface, proto, name, clazz, rtype, lflags, rb_cb, userdata);
if (!browser) { // If creation failed, clean up the client pieces to avoid leaks.
    avahi_client_free(client);
    delete poll_api; ::operator delete(cbdata); FUZZ_BAIL();
}

// Track lifecycle attributes for correct freeing later.
FUZZ_SET_ATTR_INT(browser, "created_by_new", 1);
FUZZ_SET_ATTR_INT(browser, "freed", 0);
FUZZ_SET_ATTR_PTR(browser, "parent_client", (void*)client);
// Validation: Built a valid client with poll vtable and created a record browser with a non-null callback.

// Allocate and initialize an AvahiAddress with a valid protocol and bytes.
AvahiAddress *addr = new (std::nothrow) AvahiAddress{};
if (!addr) { FUZZ_BAIL(); }
int use_v6 = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int af = use_v6 ? 10 /* AF_INET6 */ : 2 /* AF_INET */;
addr->proto = avahi_af_to_proto(af);
