import random
import string
from typing import List

# This generator produces interesting, valid NUL-terminated C strings as bytes.
# It targets Avahi APIs that expect C strings (service names/types/domains/TXT entries).
# Strategy:
# - Mix between several crafted categories:
#   - Valid service types (strict/generic)
#   - Valid/invalid-looking domain names (still valid C strings)
#   - Host names (no dots), service names (<63 chars), and FQDNs
#   - TXT entries and key/value forms (k=v, key, binary-like but still printable)
#   - Edge cases: empty string, long near-limits, strings with escapes, quotes, spaces
# - Concatenate multiple C-strings separated by NUL, ending with an extra NUL where a
#   varargs sentinel or NULL-terminated array is expected by fuzzer stubs.
# - Keep total size <= 4096 bytes.

MAX_TOTAL = 4096

VALID_TYPES = [
    b"_http._tcp", b"_ipp._tcp", b"_ssh._tcp", b"_ftp._tcp", b"_workstation._tcp",
    b"_printer._tcp", b"_airplay._tcp", b"_raop._tcp", b"_sub._tcp", b"_hap._tcp"
]

# Some candidate valid-looking domains and components
DOMAINS = [
    b"local.", b"example.local.", b"example.com.", b"sub.example.org.", b"xn--exmple-cua.com.",
]

# Service names must be < 63 chars; use safe printable subset
SAFE_CHARS = string.ascii_letters + string.digits + "-_ "


def rand_host(seed: random.Random) -> bytes:
    n = seed.randint(1, 15)
    s = ''.join(seed.choice(string.ascii_lowercase + string.digits + '-') for _ in range(n))
    s = s.strip('-') or 'host'
    return s.encode('utf-8')


def rand_service_name(seed: random.Random) -> bytes:
    n = seed.randint(1, 62)
    s = ''.join(seed.choice(SAFE_CHARS) for _ in range(n)).strip()
    s = s or 'svc'
    # Avoid leading/trailing spaces entirely to be safer
    s = s.strip()
    if not s:
        s = 'svc'
    return s.encode('utf-8')


def rand_domain(seed: random.Random) -> bytes:
    if seed.random() < 0.5:
        return seed.choice(DOMAINS)
    # Build random domain with 2-4 labels
    labels = []
    for _ in range(seed.randint(2, 4)):
        ln = seed.randint(1, 10)
        label = ''.join(seed.choice(string.ascii_lowercase + string.digits + '-') for _ in range(ln))
        label = label.strip('-') or 'a'
        labels.append(label)
    fq = '.'.join(labels) + '.'
    return fq.encode('utf-8')


def rand_service_type(seed: random.Random) -> bytes:
    if seed.random() < 0.7:
        return seed.choice(VALID_TYPES)
    # generic style: one or two underscores labels ending with _tcp/_udp
    base = '_' + ''.join(seed.choice(string.ascii_lowercase + string.digits) for _ in range(seed.randint(3, 8)))
    proto = seed.choice(['_tcp', '_udp'])
    return (base + '.' + proto).encode('utf-8')


def rand_txt_kv(seed: random.Random) -> bytes:
    key_len = seed.randint(1, 12)
    key = ''.join(seed.choice(string.ascii_lowercase + string.digits + '-') for _ in range(key_len))
    if seed.random() < 0.2:
        # key without value
        return key.encode('utf-8')
    # value part
    modes = [0, 1, 2]
    m = seed.choice(modes)
    if m == 0:
        val = ''.join(seed.choice(SAFE_CHARS) for _ in range(seed.randint(0, 30))).strip()
    elif m == 1:
        val = '/' + ''.join(seed.choice(string.ascii_lowercase + string.digits + '/-_') for _ in range(seed.randint(0, 20)))
    else:
        val = str(seed.randint(0, 65535))
    return (key + '=' + val).encode('utf-8')


def rand_subtype(seed: random.Random) -> bytes:
    # e.g., _printer._sub._http._tcp
    sub = '_' + ''.join(seed.choice(string.ascii_lowercase + string.digits) for _ in range(seed.randint(3, 10)))
    return (sub + '._sub.' + rand_service_type(seed).decode('utf-8')).encode('utf-8')


def esc_label(seed: random.Random) -> bytes:
    # Produce a label with characters that often need escaping in DNS text forms
    specials = ' "\\;()@'
    s = ''.join(seed.choice(string.ascii_letters + string.digits + specials) for _ in range(seed.randint(1, 20)))
    return s.encode('utf-8')


def rand_item(seed: random.Random) -> bytes:
    # Choose a class of C-string to include
    choice = seed.randint(0, 12)
    if choice == 0:
        return b""  # empty string
    if choice == 1:
        return rand_service_type(seed)
    if choice == 2:
        return rand_subtype(seed)
    if choice == 3:
        return rand_domain(seed)
    if choice == 4:
        return rand_host(seed)
    if choice == 5:
        return rand_service_name(seed)
    if choice == 6:
        return rand_txt_kv(seed)
    if choice == 7:
        # path-like for TXT
        return ("path=" + "/" + ''.join(seed.choice(string.ascii_lowercase + string.digits + '/-_') for _ in range(seed.randint(0, 15)))).encode('utf-8')
    if choice == 8:
        # quoted with spaces
        return ('"' + ''.join(seed.choice(SAFE_CHARS) for _ in range(seed.randint(0, 20))) + '"').encode('utf-8')
    if choice == 9:
        # label needing unescape
        return esc_label(seed)
    if choice == 10:
        # Alternative host/service name seeds
        base = rand_service_name(seed).decode('utf-8')
        # sometimes with suffix to exercise increment logic
        if seed.random() < 0.5:
            base += seed.choice(['-2', ' #2'])
        return base.encode('utf-8')
    # default: random safe word
    ln = seed.randint(1, 32)
    return ''.join(seed.choice(SAFE_CHARS) for _ in range(ln)).encode('utf-8')


def pack_cstrings(items: List[bytes]) -> bytes:
    # Pack items as NUL-terminated C strings back-to-back, and add a final NUL byte.
    # This layout works well for:
    # - varargs sentinel (extra trailing NUL makes an empty string plus sentinel acceptable)
    # - arrays of const char* pulled from a single backing buffer by the fuzzer harness
    out = bytearray()
    for it in items:
        out += it + b"\x00"
    # Extra NUL at end to serve as sentinel when needed
    out += b"\x00"
    if len(out) > MAX_TOTAL:
        return bytes(out[:MAX_TOTAL])
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    items: List[bytes] = []

    # Ensure we include at least one of each key kind frequently used in stubs
    # for better initial coverage: service type, domain, service name, TXT kv
    items.append(rand_service_type(rng))
    items.append(rand_domain(rng))
    items.append(rand_service_name(rng))
    items.append(rand_txt_kv(rng))

    # Add a few more random items (0..8)
    extra = rng.randint(0, 8)
    for _ in range(extra):
        items.append(rand_item(rng))

    # Occasionally add a full trio for service_name_join
    if rng.random() < 0.7:
        items.append(rand_service_name(rng))
        items.append(rand_service_type(rng))
        items.append(rand_domain(rng))

    # Keep total packed size within limit by trimming items if necessary
    # Approximate: ensure sum of lengths + one NUL per item + final NUL <= 4096
    total = 1  # final NUL
    trimmed: List[bytes] = []
    for it in items:
        need = len(it) + 1
        if total + need > MAX_TOTAL:
            break
        trimmed.append(it)
        total += need

    return pack_cstrings(trimmed)

import random
import string
from typing import List

# Generator for Avahi domain label bytes suitable for avahi_escape_label fuzzer stub.
# The stub reads a std::string via FUZZ_PARAM_STR and treats it as a raw label buffer
# (not NUL-terminated) with length up to 256. We therefore return bytes that represent
# a single domain label, mixing characters that exercise escaping logic:
# - plain alphanumerics (no escaping expected)
# - special characters that require backslash-escaping in textual form
# - dots ("."), which terminate labels in textual DNS and thus must be escaped when
#   part of a single label
# - backslashes ("\\") which must be escaped themselves
# - NUL byte and other control characters (0x00-0x1F, 0x7F) to test numeric escaping
# - High bytes (0x80-0xFF) to test non-ASCII handling
# - Mixed runs and boundary sizes (including empty label and max length 63 per DNS label
#   and larger up to 256 per the stub clamp)

SAFE_ALNUM = string.ascii_letters + string.digits
SPECIALS = "-_.~!$&'()*+,;=:@"  # a mix of punctuation; '.' is interesting for labels
# Control/edge bytes sets
CONTROL_BYTES = bytes(list(range(0x00, 0x20)) + [0x7F])
HIGH_BYTES = bytes(range(0x80, 0x100))
BACKSLASH = b"\\"
DOT = b"."

def _rand_bytes_from(pool: bytes, k: int, rnd: random.Random) -> bytes:
    return bytes(rnd.choice(pool) for _ in range(k))

def _make_alnum_label(rnd: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    s = ''.join(rnd.choice(SAFE_ALNUM) for _ in range(n))
    return s.encode('ascii')

def _make_special_label(rnd: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    # Mix alnum and specials, including dots that must be escaped in a single label
    choices = (SAFE_ALNUM + SPECIALS).encode('ascii') + BACKSLASH + DOT
    return _rand_bytes_from(choices, n, rnd)

def _make_control_heavy_label(rnd: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    choices = CONTROL_BYTES + b"abcXYZ09-" + BACKSLASH + DOT
    return _rand_bytes_from(choices, n, rnd)

def _make_highbyte_label(rnd: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    # Mix high bytes with a few ASCII to vary escaping
    choices = HIGH_BYTES + b"Az09-_." + BACKSLASH
    return _rand_bytes_from(choices, n, rnd)

def _pattern_backslash_runs(rnd: random.Random, n: int) -> bytes:
    # Construct alternating runs of backslashes and digits/letters
    parts: List[bytes] = []
    remaining = n
    toggle = True
    while remaining > 0:
        run = rnd.randint(1, min(5, remaining))
        if toggle:
            parts.append(BACKSLASH * run)
        else:
            parts.append(_make_alnum_label(rnd, run))
        remaining -= run
        toggle = not toggle
    return b''.join(parts)

def _pattern_dot_edges(rnd: random.Random, n: int) -> bytes:
    # Ensure dots at interesting positions but still a single label (dots must be escaped by callee)
    if n == 0:
        return b""
    base = _make_alnum_label(rnd, max(0, n - 3))
    prefix = DOT if n >= 1 and rnd.random() < 0.5 else b""
    infix = DOT if n >= 2 and rnd.random() < 0.7 else b""
    suffix = DOT if n >= 3 and rnd.random() < 0.5 else b""
    # Distribute base around dots
    return (prefix + base[:len(base)//2] + infix + base[len(base)//2:] + suffix)[:n]

def _choose_length(rnd: random.Random) -> int:
    # Favor DNS-valid label limits but sometimes exceed to test truncation/expansion behavior
    roll = rnd.random()
    if roll < 0.2:
        return 0  # empty label
    if roll < 0.55:
        return rnd.randint(1, 63)  # standard max label length
    if roll < 0.9:
        return rnd.randint(64, 128)
    return rnd.randint(129, 256)

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Select a scenario to diversify inputs
    scenario = rnd.choice([
        'alnum', 'special', 'control', 'high', 'backslashes', 'dots', 'mixed'
    ])
    n = _choose_length(rnd)

    if scenario == 'alnum':
        data = _make_alnum_label(rnd, n)
    elif scenario == 'special':
        data = _make_special_label(rnd, n)
    elif scenario == 'control':
        data = _make_control_heavy_label(rnd, n)
    elif scenario == 'high':
        data = _make_highbyte_label(rnd, n)
    elif scenario == 'backslashes':
        data = _pattern_backslash_runs(rnd, n)
    elif scenario == 'dots':
        data = _pattern_dot_edges(rnd, n)
    else:
        # mixed: concatenate segments from various categories up to n bytes
        segments = []
        remaining = n
        makers = [
            _make_alnum_label,
            _make_special_label,
            _make_control_heavy_label,
            _make_highbyte_label,
        ]
        while remaining > 0:
            maker = rnd.choice(makers)
            chunk = min(remaining, rnd.randint(1, max(1, remaining)))
            segments.append(maker(rnd, chunk))
            remaining -= chunk
        data = b''.join(segments)

    # Ensure total size <= 4096 (stub clamps to 256, we already limit to 256)
    if len(data) > 4096:
        data = data[:4096]

    return data
